'use strict';
// Personal-data surface follows qa/reference/detail-personal.png.
function personalGlyph(kind){const paths={chat:'<path d="M12 3a9 9 0 0 0-7.6 13.8L3 21l4.8-1.1A9 9 0 1 0 12 3Z"/><path d="M8 11v2m4-2v2m4-2v2" stroke="var(--symbol-color)" stroke-width="2"/>',phone:'<rect x="5" y="2" width="14" height="20" rx="3"/><path d="M10 6h4" stroke="var(--symbol-color)" stroke-width="2"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="4"/><path d="m5 8 7 5 7-5" fill="none" stroke="var(--symbol-color)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>',document:'<path d="M6 2h8l5 5v13a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2Z"/><path d="M14 2v5h5M8 12h6m-6 4h5" fill="none" stroke="var(--symbol-color)" stroke-width="2"/>',person:'<circle cx="12" cy="7" r="4"/><rect x="4" y="13" width="16" height="9" rx="4"/>'};return `<svg class="icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">${paths[kind]}</svg>`}
personalPage=function(){const entries=[['Як до вас звертатися?',state.name,'chat','orange',''],['Телефон',state.phone||'Не вказано','phone','sky',''],['Ваша ел. пошта',state.email||'Не вказано','mail','purple',''],['','Документи','document','green','Надайте нові або перегляньте надані'],['','Персональні дані','person','pink','']];return toolbar('')+`<div class="page personal-page personal-reference"><h1>Особисті дані та документи</h1><button class="personal-photo" data-action="avatar" aria-label="Поставити нове фото"><span class="avatar">${state.avatar?`<img src="${esc(state.avatar)}" alt="Фото профілю">`:icon('cat-fill')}</span><strong>Поставити нове фото</strong></button><section class="native-group personal-color-rows">${entries.map(([label,value,glyph,color,sub])=>`<button class="personal-row" data-action="personal-admin-info"><span class="personal-color-symbol ${color}">${personalGlyph(glyph)}</span><span class="personal-value">${label?`<small>${label}</small>`:''}${esc(value)}${sub?`<small class="personal-subtitle">${sub}</small>`:''}</span></button>`).join('')}</section></div>`};surfaces.personal=personalPage;
function receiptContext(){if(route.page==='file'){const file=state.files.find(f=>f.id===route.id);return {file,transaction:state.transactions.find(t=>t.id===file?.txId)}}return {transaction:currentTx()}}
function receiptTarget(transaction,file){if(file)return {page:'file',id:file.id};const attached=state.files.filter(f=>f.txId===transaction?.id).sort((a,b)=>Number(b.pinned)-Number(a.pinned))[0];return attached?{page:'file',id:attached.id}:{page:'receipt',id:transaction?.id}}
function receiptURL(transaction,file){const target=receiptTarget(transaction,file),url=new URL('index.html',location.href);url.hash=target.page+'/'+encodeURIComponent(target.id);return url.href}
function receiptShareFooter(){return '<div class="receipt-bottom receipt-share-footer"><button class="primary" data-action="share-receipt">Поділитися квитанцією</button></div>'}
const receiptBeforeShareFooter=receiptPage;receiptPage=function(){return receiptBeforeShareFooter().replace(/<div class="receipt-bottom">[\s\S]*?<\/div>/,receiptShareFooter())};
const fileBeforeShareFooter=filePage;filePage=function(){const html=fileBeforeShareFooter();return adminMode?html:html+receiptShareFooter()};
shareReceipt=async function(){const {transaction,file}=receiptContext();if(!transaction&&!file){toast('Квитанцію не знайдено');return}const url=receiptURL(transaction,file);try{if(navigator.share)await navigator.share({title:'Квитанція · демо',url});else{await navigator.clipboard.writeText(url);toast('Посилання на квитанцію скопійовано')}}catch(e){if(e.name!=='AbortError')toast('Не вдалося поділитися посиланням')}};actions['share-receipt']=()=>shareReceipt();
function receiptLinkBlock(t){const url=receiptURL(t);return `<section class="receipt-link operation-receipt-link"><button class="receipt-link-top" data-action="receipt">${icon('link')}<span><h2>Посилання на квитанцію</h2><p>${esc(url.replace(/^https?:\/\//,''))}</p></span></button><button class="secondary" data-action="share-receipt">${icon('export')}Поділитися</button></section>`}
function patternGlyph(card){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1" aria-hidden="true"><g transform="rotate(-40 12 12)"><rect x="3" y="5" width="18" height="14" rx="2"/>${card?'<path d="M3 9h18M6 15h5"/>':'<circle cx="12" cy="12" r="3"/><path d="M6 8h2m8 8h2"/>'}</g></svg>`}
const detailBeforeReceiptLinks=detail;detail=function(){const t=currentTx();let html=detailBeforeReceiptLinks();if(!t||adminMode)return html;const template=document.createElement('template');template.innerHTML=html;const existing=template.content.querySelector('.receipt-link');if(existing)existing.outerHTML=receiptLinkBlock(t);else{const body=template.content.querySelector('.reference-operation-body,.operation-body');if(body)body.insertAdjacentHTML('beforeend',receiptLinkBlock(t));else template.content.append(document.createRange().createContextualFragment(receiptLinkBlock(t)))}const pattern=template.content.querySelector('.reference-operation-pattern');if(pattern&&!pattern.querySelector('img'))pattern.insertAdjacentHTML('beforeend',`<div class="operation-pattern-glyphs">${Array.from({length:36},(_,i)=>patternGlyph(i%2)).join('')}</div>`);return template.innerHTML};
// Entry is shown on each document launch and each return from the background.
if(localStorage.getItem('demo-face')===null)localStorage.setItem('demo-face','1');
localStorage.setItem('demo-entry','1');
let entryScanTimer=null;
showEntry=function(){if(adminMode)return;if($('#modal')?.open)$('#modal').close();let layer=document.querySelector('.entry-overlay');const face=localStorage.getItem('demo-face')==='1';const unlock=()=>{clearTimeout(entryScanTimer);entryScanTimer=null;document.querySelector('.entry-overlay')?.remove();$('#app').inert=false;$('#nav').inert=false};
 if(!layer){layer=document.createElement('div');layer.className='entry-overlay';layer.setAttribute('role','dialog');layer.setAttribute('aria-modal','true');layer.setAttribute('aria-label','Вхід у демозастосунок');layer.innerHTML=`<div class="entry-content"><strong>monobank</strong><p>Демонстраційний вхід</p>${face?'<div class="face-scan" aria-label="Face ID"><svg viewBox="0 0 80 80" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"><path d="M24 6H12a6 6 0 0 0-6 6v12m50-18h12a6 6 0 0 1 6 6v12M6 56v12a6 6 0 0 0 6 6h12m32 0h12a6 6 0 0 0 6-6V56M25 28v8m30-8v8M40 28v18h-6m-7 8q13 12 26 0"/></svg></div><p>Face ID</p>':'<form class="entry-pin"><label for="entry-code">Введіть PIN-код</label><input id="entry-code" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" required autocomplete="off"><p role="alert"></p><button class="primary">Увійти</button></form>'}</div>`;document.body.append(layer);$('#app').inert=true;$('#nav').inert=true;
 if(!face){const form=layer.querySelector('form');form.onsubmit=e=>{e.preventDefault();if(form.querySelector('input').value===localStorage.getItem('demo-pin'))unlock();else{form.querySelector('[role=alert]').textContent='Невірний PIN-код';form.querySelector('input').value='';form.querySelector('input').focus()}};if(document.visibilityState==='visible')form.querySelector('input').focus()}}
 if(face&&document.visibilityState==='visible'&&!entryScanTimer)entryScanTimer=setTimeout(unlock,1100);
};actions['lock-demo']=()=>showEntry();
window.entryChecked=true;showEntry();
// Entry lifecycle is owned by faithful-entry.js.

render();
// Remove legacy empty receipt decoration and a stray markup character.
const paperBeforeCleanup=paper;paper=function(t){return paperBeforeCleanup(t).replace('<span class="brand">monobank</span><<br><br></small>','<span class="brand">monobank</span>').replace('<div class="paper-demo"></div>','')};
